        record = {
            "timestamp": datetime.now().isoformat(),
            "team_name": team_name,
            "score": score,
            "players": [p.to_dict() for p in players],
            "game_config": game_config.to_dict()
        }
        self.history.append(record)
        self._update_statistics(record)

    def _update_statistics(self, record: Dict):
        team_name = record["team_name"]
        score = record["score"]
        players = record["players"]

        # Update role effectiveness
        for p in players:
            role = p["role"]
            if role not in self.role_effectiveness:
                self.role_effectiveness[role] = {"total_score": 0.0, "count": 0}
            self.role_effectiveness[role]["total_score"] += score
            self.role_effectiveness[role]["count"] += 1

        # Update team composition patterns
        roles = tuple(sorted([p["role"] for p in players]))
        key = f"{team_name}:{roles}"
        if key not in self.team_composition_patterns:
            self.team_composition_patterns[key] = {"total_score": 0.0, "count": 0}
        self.team_composition_patterns[key]["total_score"] += score
        self.team_composition_patterns[key]["count"] += 1

    def get_suggestions(self, team: Team, game_config: GameConfig) -> List[str]:
        suggestions = []
